    "offpage": "放在页面可视区外（多数提取器会裁掉，边界样本）",
    "vanish":  "Word 内置\"字体→隐藏\"属性（vanish）",
    "meta":    "藏进文档元数据（备注字段）",
    "dark":    "照片底部角落正常深色小字",
    "light":   "照片底部浅灰小字（铅笔感）",
}


def _cjk_font(text):
    return "china-s" if any("\u4e00" <= ch <= "\u9fff" for ch in text) else "helv"


def inject_pdf(src, dst, text, mode):
    doc = fitz.open(src)
    page = doc[-1]
    font = _cjk_font(text)
    if mode == "tr3":
        page.insert_text((60, 46), text, fontsize=1.0, render_mode=3, fontname=font)
    elif mode == "white":
        page.insert_text((60, 46), text, fontsize=1.0, color=(1, 1, 1), fontname=font)
    elif mode == "ghost":
        page.insert_text((60, 46), text, fontsize=1.0, fill_opacity=0.03, fontname=font)
    elif mode == "tiny":
        page.insert_text((60, 46), text, fontsize=0.5, color=(0.93, 0.93, 0.93), fontname=font)
    elif mode == "offpage":
        page.insert_text((-180, 46), text, fontsize=1.0, fontname=font)
    else:
        raise ValueError(mode)
    doc.save(dst)


def _add_vanish(run):
    rPr = run._element.get_or_add_rPr()
    if rPr.find(qn("w:vanish")) is None:
        rPr.append(rPr.makeelement(qn("w:vanish"), {}))


def inject_docx(src, dst, text, mode):
    doc = Document(src)
    if mode == "meta":
        doc.core_properties.comments = text
    else:
        run = doc.add_paragraph().add_run(text)
        if mode == "white":
            run.font.color.rgb = RGBColor(0xFF, 0xFF, 0xFF)
        elif mode == "vanish":
            _add_vanish(run)
        elif mode == "tiny":
            run.font.size = Pt(1)
        else:
            raise ValueError(mode)
    doc.save(dst)


def tamper_file(src, dst, text, mode):
    """按扩展名分发。返回 dst。"""
    ext = os.path.splitext(src)[1].lower()
    if ext == ".pdf":
        inject_pdf(src, dst, text, mode)
    elif ext == ".docx":
        inject_docx(src, dst, text, mode)
    else:
        raise ValueError(f"unsupported: {ext}")
    return dst


import os  # noqa: E402  (tamper_file 里用到，放底部避免循环)

