        if ws.sheet_state != "visible":
            vals = [str(c.value) for row in ws.iter_rows() for c in row if c.value is not None]
            if vals:
                hidden.append("[隐藏表 %s] %s" % (ws.title, " / ".join(vals)[:100]))
                res["findings"].setdefault("hidden_sheet", []).append(
                    f"{ws.title}: {' / '.join(vals)[:80]}")
        for row in ws.iter_rows():
            for cell in row:
                if cell.value is None:
                    continue
                val = str(cell.value)
                if cell.font and cell.font.color and cell.font.color.rgb in ("FFFFFFFF", "00FFFFFF"):
                    hidden.append(val)
                    res["findings"].setdefault("white_text_cell", []).append(val[:80])
                if cell.comment and INSTRUCTION_RE.search(cell.comment.text):
                    hidden.append(cell.comment.text)
                    res["findings"].setdefault("comment_instruction", []).append(
                        cell.comment.text[:80])
                if INSTRUCTION_RE.search(val):
                    res["findings"].setdefault("instruction_pattern_cell", []).append(val[:80])
    res["hidden_text"] = " | ".join(hidden)[:500]
    if any(rule not in INFO_ONLY for rule in res["findings"]):
        res["verdict"] = "suspicious"
    return res


def scan_image(path):
    text = _ocr(path)
    res = {"file": path, "format": "image", "verdict": "clean", "findings": {},
           "hidden_text": ""}
    m = INSTRUCTION_RE.search(text)
    if m:
        res["findings"]["instruction_pattern_ocr"] = [m.group(0)]
        res["hidden_text"] = m.group(0)
    if res["findings"]:
        res["verdict"] = "suspicious"
    return res


def scan(path):
    p = path.lower()
    if p.endswith(".pdf"):
        return scan_pdf(path)
    if p.endswith(".docx"):
        return scan_docx(path)
    if p.endswith((".png", ".jpg", ".jpeg", ".bmp")):
        return scan_image(path)
    raise ValueError(f"unsupported file: {path}")


def is_flagged(result):
    return result["verdict"] == "suspicious"


if __name__ == "__main__":
    for f in sys.argv[1:]:
        r = scan(f)
        tag = "SUSPICIOUS" if is_flagged(r) else "clean"
        print(f"{tag:10s} {f}")
        for rule, hits in r["findings"].items():
            print(f"    {rule}: {hits[:2]}")

