    try:
        j = json.load(open(path, encoding="utf-8"))
        cells = ["".join(c.get("source", [])) for c in j.get("cells", [])]
    except Exception as e:
        res["findings"]["parse_error"] = [str(e)[:60]]
        res["verdict"] = "suspicious"
        return res
    text = "\n".join(cells)
    m = INSTRUCTION_RE.search(text)
    if m:
        res["findings"]["instruction_pattern"] = [m.group(0)]
        res["hidden_text"] = m.group(0)
    if res["findings"]:
        res["verdict"] = "suspicious"
    return res


def scan(path):
    p = path.lower()
    if p.endswith(".pdf"):
        return scan_pdf(path)
    if p.endswith(".docx"):
        return scan_docx(path)
    if p.endswith(".ipynb"):
        return scan_ipynb(path)
    if p.endswith((".png", ".jpg", ".jpeg", ".bmp")):
        return scan_image(path)
    raise ValueError(f"unsupported file: {path}")


# 仅记录不改变判定结果的规则（任何非空元数据都算 info，只有命中指令模式才算可疑）
INFO_ONLY = {"metadata_present"}


def is_flagged(result):
    return any(rule not in INFO_ONLY for rule in result["findings"])


if __name__ == "__main__":
    for f in sys.argv[1:]:
        r = scan(f)
        tag = "SUSPICIOUS" if is_flagged(r) else "clean"
        print(f"{tag:10s} {f}")
        for rule, hits in r["findings"].items():
            print(f"    {rule}: {hits[:2]}")

